mapper.select:
/*	designReport.selectDesignCount */
SELECT
	COUNT(DESIGN_IDX) as cnt
FROM 	
	lab_design
WHERE 1 = 1
	
		 
		AND DOC_OWNER = #{userId} 
		
	    
	    AND DOC_OWNER IN (
	    	SELECT USER_ID from lab_team_manager_view ltmv
			WHERE ltmv.TEAM_MANAGER_ID = #{userId}
	    ) 
	    
	    			    
	    
	    			    
	    
		 AND DOC_OWNER = #{userId} 
	
	AND IS_DELETE = 'N'
	AND IS_LAST = 'Y'

/* designReport.selectDesignList */ SELECT DESIGN_IDX , PRODUCT_CODE , SAP_CODE , TITLE , PRODUCT_NAME , CONTENTS , VERSION_NO , IS_DELETE , IS_LAST , STATUS , REG_USER , DOC_OWNER , DOC_NO , FN_GET_USER_NAME(ld.DOC_OWNER) as DOC_OWNER_NAME , FN_GET_CODE_NAME('DOC_STATUS', ld.STATUS) AS STATUS_TXT , (SELECT COUNT(*) FROM lab_design WHERE 1 = 1 AND DOC_NO = ld.DOC_NO AND IS_LAST = 'N' AND VERSION_NO < ld.VERSION_NO AND IS_DELETE = 'N' ) as CHILD_CNT FROM lab_design ld WHERE 1 = 1 AND DOC_NO in ( SELECT tmp.DOC_NO FROM ( SELECT row_number() over (order by DESIGN_IDX DESC) as rnum , DOC_NO FROM lab_design WHERE 1 = 1
AND DOC_OWNER = #{userId}
AND DOC_OWNER IN ( SELECT USER_ID from lab_team_manager_view ltmv WHERE ltmv.TEAM_MANAGER_ID = #{userId} )
AND DOC_OWNER = #{userId}
AND IS_DELETE = 'N' AND IS_LAST = 'Y'
) tmp WHERE rnum between 1 and 10 ) ORDER BY DOC_NO DESC, VERSION_NO DESC, DESIGN_IDX DESC

mapper.insert:
/*	designReport.insertDesign */
INSERT INTO lab_design(
	DESIGN_IDX
	, PRODUCT_CODE
	, SAP_CODE
	, TITLE
	, PRODUCT_NAME
	, CONTENTS
	, VERSION_NO
	, IS_DELETE
	, IS_LAST
	, STATUS
	, REG_USER
	, DOC_OWNER		
	, DOC_NO		
)VALUES(
	#{idx}
	, #{productCode}
	, #{sapCode}
	, #{title}
	, #{productName}
	, #{contents}
	, 1
	, 'N'
	, 'Y'
	, #{status}
	, #{userId}
	, (SELECT ifnull(MAX(ld.DOC_NO),0)+1 FROM lab_design ld WHERE 1 = 1)	
)

mapper.update:
/*	designReport.updateDesign */
	UPDATE 
		lab_design
	SET 
		PRODUCT_CODE = #{productCode}
		, SAP_CODE = #{sapCode}
		, TITLE = #{title}
		, PRODUCT_NAME = #{productName}
		, CHANGE_COMMENT = #{changeComment}
		, CHANGE_TIME = #{changeTime}
		, CONTENTS = #{contents}
		
		, STATUS = #{status}
		
	WHERE 1 = 1
		AND DESIGN_IDX = #{idx}

mapper.delete:
/*	designReport.deleteChangeList */
	DELETE
	FROM lab_design_change_info
	WHERE 1 = 1
		AND DESIGN_IDX = #{idx}

