INSERT INTO lab_design(
	DESIGN_IDX
	, PRODUCT_CODE
	, SAP_CODE
	, TITLE
	, PRODUCT_NAME
	, CONTENTS
	, VERSION_NO
	, IS_DELETE
	, IS_LAST
	, STATUS
	, REG_USER
	, DOC_OWNER		
	, DOC_NO		
)VALUES(
	#{idx}
	, #{productCode}
	, #{sapCode}
	, #{title}
	, #{productName}
	, #{contents}
	, (SELECT ifnull(MAX(ld.VERSION_NO),0)+1 FROM lab_design ld WHERE 1 = 1 AND DOC_NO = #{docNo})	
	, 'N'
	, 'Y'
	, #{status}
	, #{userId}
	, #{userId}
	, #{docNo}
